//! Command line parsing.
//!
//! A small hand written argument parser that mirrors the behaviour (and the
//! diagnostics) of the argument parser used by the original tool.

use std::ffi::{OsStr, OsString};
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::Path;

/// Identifier of every argument known to the command.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Id {
    InputFile,
    Cols,
    Len,
    Format,
    Color,
    Array,
    Func,
    Places,
    Prefix,
    Help,
    Version,
}

struct ArgDef {
    id: Id,
    short: char,
    long: &'static str,
    value_name: Option<&'static str>,
    possible: &'static [&'static str],
}

/// Definition order matters: it is used for suggestions and help output.
const ARGS: [ArgDef; 10] = [
    ArgDef { id: Id::Cols, short: 'c', long: "cols", value_name: Some("columns"), possible: &[] },
    ArgDef { id: Id::Len, short: 'l', long: "len", value_name: Some("len"), possible: &[] },
    ArgDef {
        id: Id::Format,
        short: 'f',
        long: "format",
        value_name: Some("format"),
        possible: &["o", "x", "X", "b"],
    },
    ArgDef { id: Id::Color, short: 't', long: "color", value_name: Some("color"), possible: &["0", "1"] },
    ArgDef {
        id: Id::Array,
        short: 'a',
        long: "array",
        value_name: Some("array_format"),
        possible: &["r", "c", "g", "p", "k", "j", "s", "f"],
    },
    ArgDef { id: Id::Func, short: 'u', long: "func", value_name: Some("func_length"), possible: &[] },
    ArgDef { id: Id::Places, short: 'p', long: "places", value_name: Some("func_places"), possible: &[] },
    ArgDef { id: Id::Prefix, short: 'r', long: "prefix", value_name: Some("prefix"), possible: &["0", "1"] },
    ArgDef { id: Id::Help, short: 'h', long: "help", value_name: None, possible: &[] },
    ArgDef { id: Id::Version, short: 'V', long: "version", value_name: None, possible: &[] },
];

pub const VERSION: &str = "0.7.0";
pub const NAME: &str = "hx";

fn def(id: Id) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.id == id)
}

fn takes_value(id: Id) -> bool {
    match id {
        Id::InputFile => true,
        _ => def(id).map(|d| d.value_name.is_some()).unwrap_or(false),
    }
}

fn possible_values(id: Id) -> &'static [&'static str] {
    def(id).map(|d| d.possible).unwrap_or(&[])
}

fn display(id: Id) -> String {
    match id {
        Id::InputFile => "[INPUTFILE]".to_string(),
        _ => {
            let d = def(id).expect("known argument");
            match d.value_name {
                Some(v) => format!("--{} <{}>", d.long, v),
                None => format!("--{}", d.long),
            }
        }
    }
}

/// Parsed values of the command line.
#[derive(Default, Debug, Clone)]
pub struct Matches {
    values: Vec<(Id, Option<String>)>,
}

impl Matches {
    pub fn get(&self, id: Id) -> Option<&str> {
        self.values
            .iter()
            .find(|(i, _)| *i == id)
            .and_then(|(_, v)| v.as_deref())
    }

    pub fn contains(&self, id: Id) -> bool {
        self.values.iter().any(|(i, _)| *i == id)
    }

    fn remove(&mut self, id: Id) -> bool {
        let before = self.values.len();
        self.values.retain(|(i, _)| *i != id);
        before != self.values.len()
    }

    fn start(&mut self, id: Id) {
        if !self.contains(id) {
            self.values.push((id, None));
        }
    }

    fn set(&mut self, id: Id, val: String) {
        if let Some(entry) = self.values.iter_mut().find(|(i, _)| *i == id) {
            entry.1 = Some(val);
        }
    }

    fn ids(&self) -> Vec<Id> {
        self.values.iter().map(|(i, _)| *i).collect()
    }
}

/// Result of a failed or short-circuited parse.
pub enum Outcome {
    /// Help text to print on stdout (exit status 0).
    Help(String),
    /// Version text to print on stdout (exit status 0).
    Version(String),
    /// Error text to print on stderr (exit status 2).
    Error(String),
}

struct Pending {
    id: Id,
    vals: Vec<OsString>,
}

enum State {
    ValuesDone,
    Opt(Id),
}

enum Step {
    ValuesDone,
    Opt(Id),
    NoMatchingArg(String),
    UnneededAttachedValue { rest: String, used: Vec<Id>, arg: String },
}

struct Parser {
    bin: String,
    matches: Matches,
    pending: Option<Pending>,
}

const TRY_HELP: &str = "\n\nFor more information, try '--help'.\n";

fn lossy(s: &OsStr) -> String {
    String::from_utf8_lossy(s.as_bytes()).into_owned()
}

impl Parser {
    fn usage(&self, used: &[Id]) -> String {
        let mut s = format!("Usage: {}", self.bin);
        if used.is_empty() {
            s.push_str(" [OPTIONS] [INPUTFILE]");
            return s;
        }
        let mut opts: Vec<Id> = Vec::new();
        let mut has_pos = false;
        for id in used {
            if *id == Id::InputFile {
                has_pos = true;
            } else if !opts.contains(id) {
                opts.push(*id);
            }
        }
        for id in opts {
            s.push(' ');
            s.push_str(&display(id));
        }
        if has_pos {
            s.push_str(" <INPUTFILE>");
        } else {
            s.push_str(" [INPUTFILE]");
        }
        s
    }

    fn help_text(&self) -> String {
        format!(
            "Futuristic take on hexdump, made in Rust.\n\
\n\
\n\
Usage: {} [OPTIONS] [INPUTFILE]\n\
\n\
Arguments:\n\
\x20 [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\
\n\
Options:\n\
\x20 -c, --cols <columns>        Set column length\n\
\x20 -l, --len <len>             Set <len> bytes to read\n\
\x20 -f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]\n\
\x20 -t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]\n\
\x20 -a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]\n\
\x20 -u, --func <func_length>    Set function wave length\n\
\x20 -p, --places <func_places>  Set function wave output decimal places\n\
\x20 -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]\n\
\x20 -h, --help                  Print help\n\
\x20 -V, --version               Print version\n",
            self.bin
        )
    }

    fn values_list(possible: &[&str]) -> String {
        if possible.is_empty() {
            return String::new();
        }
        let list: Vec<String> = possible.iter().map(|v| escape(v)).collect();
        format!("\n  [possible values: {}]", list.join(", "))
    }

    fn err_empty_value(&self, id: Id) -> Outcome {
        Outcome::Error(format!(
            "error: a value is required for '{}' but none was supplied{}{}",
            display(id),
            Self::values_list(possible_values(id)),
            TRY_HELP
        ))
    }

    fn err_invalid_value(&self, id: Id, val: &str) -> Outcome {
        let possible = possible_values(id);
        let mut s = if val.is_empty() {
            format!("error: a value is required for '{}' but none was supplied", display(id))
        } else {
            format!("error: invalid value '{}' for '{}'", val, display(id))
        };
        s.push_str(&Self::values_list(possible));
        if let Some(sugg) = did_you_mean(val, possible.iter().copied()).pop() {
            s.push_str(&format!("\n\n  tip: a similar value exists: '{}'", sugg));
        }
        s.push_str(TRY_HELP);
        Outcome::Error(s)
    }

    fn err_invalid_utf8(&self) -> Outcome {
        Outcome::Error(format!(
            "error: invalid UTF-8 was detected in one or more arguments\n\n{}{}",
            self.usage(&[]),
            TRY_HELP
        ))
    }

    fn err_conflict(&self, id: Id) -> Outcome {
        Outcome::Error(format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}{}",
            display(id),
            self.usage(&[]),
            TRY_HELP
        ))
    }

    fn err_unknown(&self, arg: &str, suggestion: Option<String>, trailing_tip: bool, used: &[Id]) -> Outcome {
        let mut s = format!("error: unexpected argument '{}' found", arg);
        let mut suggested = false;
        if let Some(sugg) = suggestion {
            s.push_str("\n\n");
            suggested = true;
            s.push_str(&format!("  tip: a similar argument exists: '{}'", sugg));
        }
        if trailing_tip {
            if !suggested {
                s.push('\n');
            }
            s.push_str(&format!("\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg));
        }
        s.push_str("\n\n");
        s.push_str(&self.usage(used));
        s.push_str(TRY_HELP);
        Outcome::Error(s)
    }

    fn err_too_many_values(&self, val: &str, arg: &str, used: &[Id]) -> Outcome {
        Outcome::Error(format!(
            "error: unexpected value '{}' for '{}' found; no more were expected\n\n{}{}",
            val,
            arg,
            self.usage(used),
            TRY_HELP
        ))
    }

    fn resolve_pending(&mut self) -> Result<(), Outcome> {
        match self.pending.take() {
            None => Ok(()),
            Some(p) => self.react(p.id, p.vals).map(|_| ()),
        }
    }

    fn react(&mut self, id: Id, vals: Vec<OsString>) -> Result<Step, Outcome> {
        self.resolve_pending()?;
        if takes_value(id) && vals.is_empty() {
            return Err(self.err_empty_value(id));
        }
        match id {
            Id::Help => Err(Outcome::Help(self.help_text())),
            Id::Version => Err(Outcome::Version(format!("{} {}\n", NAME, VERSION))),
            _ => {
                if self.matches.remove(id) {
                    return Err(self.err_conflict(id));
                }
                self.matches.start(id);
                for raw in vals {
                    let val = match raw.into_string() {
                        Ok(v) => v,
                        Err(_) => return Err(self.err_invalid_utf8()),
                    };
                    let possible = possible_values(id);
                    if !possible.is_empty() && !possible.contains(&val.as_str()) {
                        return Err(self.err_invalid_value(id, &val));
                    }
                    self.matches.set(id, val);
                }
                Ok(Step::ValuesDone)
            }
        }
    }

    fn parse_opt_value(&mut self, id: Id, attached: Option<OsString>) -> Result<Step, Outcome> {
        match attached {
            Some(v) => {
                self.react(id, vec![v])?;
                Ok(Step::ValuesDone)
            }
            None => {
                self.resolve_pending()?;
                self.pending = Some(Pending { id, vals: Vec::new() });
                Ok(Step::Opt(id))
            }
        }
    }

    fn parse_long(&mut self, name: &[u8], value: Option<&[u8]>) -> Result<Step, Outcome> {
        let name = match std::str::from_utf8(name) {
            Ok(n) => n.to_string(),
            Err(_) => return Ok(Step::NoMatchingArg(lossy(OsStr::from_bytes(name)))),
        };
        let found = ARGS.iter().find(|a| a.long == name);
        match found {
            Some(d) => {
                if d.value_name.is_some() {
                    self.parse_opt_value(d.id, value.map(|v| OsStr::from_bytes(v).to_os_string()))
                } else if let Some(rest) = value {
                    let mut used = self.matches.ids();
                    used.push(d.id);
                    Ok(Step::UnneededAttachedValue {
                        rest: lossy(OsStr::from_bytes(rest)),
                        used,
                        arg: display(d.id),
                    })
                } else {
                    self.react(d.id, Vec::new())
                }
            }
            None => Ok(Step::NoMatchingArg(name)),
        }
    }

    fn parse_short(&mut self, flags: &[u8]) -> Result<Step, Outcome> {
        let (valid, invalid): (&str, Option<&[u8]>) = match std::str::from_utf8(flags) {
            Ok(s) => (s, None),
            Err(e) => {
                let (v, rest) = flags.split_at(e.valid_up_to());
                (std::str::from_utf8(v).unwrap_or(""), Some(rest))
            }
        };
        let mut ret = Step::ValuesDone;
        let mut iter = valid.char_indices().peekable();
        while let Some((_, c)) = iter.next() {
            let found = ARGS.iter().find(|a| a.short == c);
            let d = match found {
                Some(d) => d,
                None => return Ok(Step::NoMatchingArg(format!("-{}", c))),
            };
            if d.value_name.is_none() {
                ret = self.react(d.id, Vec::new())?;
                continue;
            }
            // Remaining part of the cluster is the attached value.
            let rest: &[u8] = match iter.peek() {
                Some((idx, _)) => &flags[*idx..],
                None => invalid.unwrap_or(&[]),
            };
            let val: Option<&[u8]> = if rest.is_empty() { None } else { Some(rest) };
            let val = match val {
                Some(v) if v.first() == Some(&b'=') => Some(&v[1..]),
                other => other,
            };
            return self.parse_opt_value(d.id, val.map(|v| OsStr::from_bytes(v).to_os_string()));
        }
        if let Some(rest) = invalid {
            return Ok(Step::NoMatchingArg(format!("-{}", lossy(OsStr::from_bytes(rest)))));
        }
        Ok(ret)
    }

    fn did_you_mean_error(&mut self, arg: &str, trailing: bool) -> Outcome {
        let longs = ARGS.iter().map(|a| a.long);
        let sugg = did_you_mean(arg, longs).pop();
        if let Some(name) = &sugg {
            if let Some(d) = ARGS.iter().find(|a| a.long == name) {
                self.matches.start(d.id);
            }
        }
        let used = self.matches.ids();
        let trailing_tip = sugg.is_none() && !trailing;
        self.err_unknown(
            &format!("--{}", arg),
            sugg.map(|s| format!("--{}", s)),
            trailing_tip,
            &used,
        )
    }

    fn run(&mut self, args: &[OsString]) -> Result<(), Outcome> {
        let mut trailing = false;
        let mut state = State::ValuesDone;
        let mut pos_counter = 1usize;

        for arg in args {
            let bytes = arg.as_bytes();
            if !trailing {
                if bytes == b"--" {
                    trailing = true;
                    continue;
                }
                let step = if let Some(rest) = bytes.strip_prefix(b"--") {
                    let (name, value) = match rest.iter().position(|b| *b == b'=') {
                        Some(p) => (&rest[..p], Some(&rest[p + 1..])),
                        None => (rest, None),
                    };
                    Some(self.parse_long(name, value)?)
                } else if bytes.len() > 1 && bytes[0] == b'-' {
                    let step = self.parse_short(&bytes[1..])?;
                    if let Step::NoMatchingArg(a) = step {
                        let _ = self.resolve_pending();
                        return Err(self.err_unknown(&a, None, !trailing, &[]));
                    }
                    Some(step)
                } else {
                    None
                };
                match step {
                    Some(Step::ValuesDone) => {
                        state = State::ValuesDone;
                        continue;
                    }
                    Some(Step::Opt(id)) => {
                        state = State::Opt(id);
                        continue;
                    }
                    Some(Step::NoMatchingArg(a)) => {
                        let _ = self.resolve_pending();
                        return Err(self.did_you_mean_error(&a, trailing));
                    }
                    Some(Step::UnneededAttachedValue { rest, used, arg }) => {
                        let _ = self.resolve_pending();
                        return Err(self.err_too_many_values(&rest, &arg, &used));
                    }
                    None => {}
                }
                if let State::Opt(_) = state {
                    if let Some(p) = self.pending.as_mut() {
                        p.vals.push(arg.clone());
                    }
                    state = State::ValuesDone;
                    continue;
                }
            }

            if pos_counter == 1 {
                self.resolve_pending()?;
                self.pending = Some(Pending { id: Id::InputFile, vals: vec![arg.clone()] });
                pos_counter += 1;
                state = State::ValuesDone;
            } else {
                let _ = self.resolve_pending();
                let shown = lossy(arg);
                return Err(self.err_unknown(&shown, None, false, &[]));
            }
        }
        self.resolve_pending()?;
        Ok(())
    }
}

/// Quote a possible value when it contains whitespace.
fn escape(v: &str) -> String {
    if v.chars().any(|c| c.is_whitespace()) {
        format!("{:?}", v)
    } else {
        v.to_string()
    }
}

/// Jaro similarity between two strings.
pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && *ac == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut b_iter = b_flags.iter().zip(b.iter());
        for (a_flag, ch1) in a_flags.iter().zip(a.iter()) {
            if *a_flag {
                for (b_flag, ch2) in b_iter.by_ref() {
                    if !*b_flag {
                        continue;
                    }
                    if ch1 != ch2 {
                        transpositions += 1;
                    }
                    break;
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        let m = matches as f64;
        ((m / a_len as f64) + (m / b_len as f64) + ((matches - transpositions) as f64 / m)) / 3.0
    }
}

/// Candidates similar to `v`, sorted by increasing confidence.
pub fn did_you_mean<'a, I>(v: &str, possible: I) -> Vec<String>
where
    I: IntoIterator<Item = &'a str>,
{
    let mut candidates: Vec<(f64, String)> = possible
        .into_iter()
        .map(|pv| (jaro(v, pv), pv.to_string()))
        .filter(|(c, _)| *c > 0.7)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.into_iter().map(|(_, s)| s).collect()
}

/// Name used in usage strings, derived from argv[0].
fn bin_name(argv0: Option<&OsString>) -> String {
    argv0
        .and_then(|a| Path::new(a).file_name())
        .and_then(|f| f.to_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| NAME.to_string())
}

/// Parse the full argument vector (including argv[0]).
pub fn parse(argv: Vec<OsString>) -> Result<Matches, Outcome> {
    let bin = bin_name(argv.first());
    let rest: Vec<OsString> = argv.into_iter().skip(1).collect();
    let mut p = Parser { bin, matches: Matches::default(), pending: None };
    p.run(&rest)?;
    Ok(p.matches)
}

#[allow(dead_code)]
fn to_os(v: Vec<u8>) -> OsString {
    OsString::from_vec(v)
}
