//! Function wave output.
//!
//! When `--func <func_length>` is supplied, no input is read at all. Instead
//! the tool prints `func_length` samples of a quarter sine wave, i.e. the
//! values
//!
//! ```text
//! sin(i / n * PI / 2)   for i in 0..n
//! ```
//!
//! Each sample is formatted with a fixed number of decimal places (four by
//! default, configurable with `--places <func_places>`) and followed by a
//! comma. Ten samples are printed per line and the output is terminated by a
//! final newline, so that a length that is a multiple of ten ends with an
//! empty line.
//!
//! Example for `--func 5 --places 3`:
//!
//! ```text
//! 0.000,0.309,0.588,0.809,0.951,
//! ```
//!
//! This can be handy to generate lookup tables for embedded software, LED
//! fading, simple audio synthesis and similar tasks.

use std::f64::consts::PI;

/// Number of samples printed on each output line.
pub const SAMPLES_PER_LINE: u64 = 10;

/// Default number of decimal places used when `--places` is not supplied.
pub const DEFAULT_PLACES: usize = 4;

/// Compute the `index`-th sample of a quarter wave made of `length` samples.
///
/// The first sample is always `0.0` and the samples approach (but never
/// reach) `1.0` as `index` approaches `length`.
pub fn wave_value(index: u64, length: u64) -> f64 {
    let x = index as f64;
    let n = length as f64;
    (x / n * PI / 2.0).sin()
}

/// Returns true when a line break has to follow the sample at `index`.
fn ends_line(index: u64) -> bool {
    (index + 1) % SAMPLES_PER_LINE == 0
}

/// Print `length` samples of the quarter wave to stdout.
///
/// * `length` - number of samples to print.
/// * `places` - number of decimal places of every sample.
///
/// Output is streamed to stdout as it is produced; a final newline is always
/// printed, even when `length` is zero.
///
/// # Panics
///
/// Panics when stdout cannot be written to (for example when the reading
/// end of a pipe has been closed), or when `places` exceeds the maximum
/// precision supported by the formatting machinery.
pub fn output_function(length: u64, places: usize) {
    let mut index: u64 = 0;
    while index < length {
        let value = wave_value(index, length);
        // Every sample is followed by a comma, including the last one.
        let formatted_sample = format!("{:.*},", places, value);
        print!("{}", formatted_sample);
        if ends_line(index) {
            println!();
        }
        index += 1;
    }
    println!();
}
