}

/// Parse an optional unsigned integer option.
fn parse_usize(m: &Matches, id: Id, flag: &str, default: usize) -> Result<usize, ()> {
    match m.get(id) {
        None => Ok(default),
        Some(v) => v.parse::<usize>().map_err(|e| report_int_error(flag, &e)),
    }
}

/// Parse an optional unsigned 64 bit integer option.
fn parse_u64(m: &Matches, id: Id, flag: &str, default: u64) -> Result<u64, ()> {
    match m.get(id) {
        None => Ok(default),
        Some(v) => v.parse::<u64>().map_err(|e| report_int_error(flag, &e)),
    }
}

/// Decide whether the output should be colorized.
///
/// An explicit `--color` value always wins. Otherwise color is used when
/// stdout is a terminal and the `NO_COLOR` environment variable is not set.
fn use_color(m: &Matches) -> bool {
    match m.get(Id::Color) {
        Some("1") => true,
        Some(_) => false,
        None => std::env::var_os("NO_COLOR").is_none() && io::stdout().is_terminal(),
    }
}

/// Color index used for a byte.
fn byte_color(byte: u8) -> u8 {
    if byte == 0 {
        22
    } else {
        byte
    }
}

/// Character displayed in the ASCII column for a byte.
fn printable(byte: u8) -> char {
    if (0x20..=0x7e).contains(&byte) {
        byte as char
    } else {
        '.'
    }
}

/// Settings of the hexdump view.
#[derive(Clone, Copy, Debug)]
pub struct DumpOptions {
    pub cols: usize,
    pub format: Format,
    pub prefix: bool,
    pub color: bool,
}

/// Write one octet of the hex column (including its trailing space).
fn write_octet<W: Write>(out: &mut W, byte: u8, opts: &DumpOptions) {
    let text = opts.format.render(byte, opts.prefix);
    if opts.color {
        let _ = write!(out, "\x1b[38;5;{}m{}{} ", byte_color(byte), text, RESET);
    } else {
        let _ = write!(out, "{} ", text);
    }
}

/// Write the ASCII column of a line.
fn write_ascii<W: Write>(out: &mut W, bytes: &[u8], opts: &DumpOptions) {
    for &byte in bytes {
        if opts.color {
            let _ = write!(out, "\x1b[38;5;{}m{}{}", byte_color(byte), printable(byte), RESET);
        } else {
            let _ = write!(out, "{}", printable(byte));
        }
    }
}

/// Write a complete line of the dump (no padding needed).
fn write_full_line<W: Write>(out: &mut W, offset: usize, bytes: &[u8], opts: &DumpOptions) {
    let _ = write!(out, "{:#08x}: ", offset);
    for &byte in bytes {
        write_octet(out, byte, opts);
    }
    write_ascii(out, bytes, opts);
    let _ = writeln!(out);
}

/// Write the final (possibly partial or empty) line of the dump, padding the
/// hex column so the ASCII column lines up with the previous lines.
fn write_last_line<W: Write>(out: &mut W, offset: usize, bytes: &[u8], opts: &DumpOptions) {
    let _ = write!(out, "{:#08x}: ", offset);
    for &byte in bytes {
        write_octet(out, byte, opts);
    }
    let missing = opts.cols.wrapping_sub(bytes.len());
    let padding = missing.wrapping_mul(PAD_WIDTH);
    write_padding(out, padding);
    write_ascii(out, bytes, opts);
    let _ = writeln!(out);
}

/// Hexdump view of `data`.
///
/// Every line starts with the offset of its first byte, followed by the
/// octets and their printable representation. A line is emitted as soon as
/// it holds `cols` octets (or one octet when `cols` is zero); the remaining
/// bytes - possibly none - always form a final padded line. The view ends
/// with the total number of bytes.
pub fn print_dump<W: Write>(out: &mut W, data: &[u8], opts: &DumpOptions) {
    let step = opts.cols.max(1);
    let full = data.len() / step;
    let mut offset = 0usize;
    for line in data.chunks(step).take(full) {
        write_full_line(out, offset, line, opts);
        offset += line.len();
    }
    write_last_line(out, offset, &data[offset..], opts);
    let _ = writeln!(out, "   bytes: {}", data.len());
}

/// Source code array view of `data`.
pub fn print_array<W: Write>(out: &mut W, data: &[u8], cols: usize, flavour: ArrayFormat) {
    let _ = writeln!(out, "{}", flavour.header(data.len()));
    let _ = write!(out, "    ");
    let last = data.len().saturating_sub(1);
    let mut in_line = 0usize;
    for (i, &byte) in data.iter().enumerate() {
        let _ = write!(out, "{}", flavour.element(byte));
        if i != last || flavour.trailing_separator() {
            let _ = write!(out, "{}", flavour.separator());
        }
        in_line += 1;
        if in_line >= cols {
            let _ = write!(out, "\n    ");
            in_line = 0;
        }
    }
    let _ = writeln!(out);
    let _ = writeln!(out, "{}", flavour.footer());
}

/// Read the whole input, limited to `len` bytes when `len` is not zero.
fn read_input(input: &mut dyn Read, len: u64) -> io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    if len > 0 {
        input.take(len).read_to_end(&mut buf)?;
    } else {
        input.read_to_end(&mut buf)?;
    }
    Ok(buf)
}

/// Print the outcome of a short-circuited command line parse and return the
/// exit status.
fn finish_parse(outcome: Outcome) -> i32 {
    match outcome {
        Outcome::Help(text) | Outcome::Version(text) => {
            let stdout = io::stdout();
            let mut out = stdout.lock();
            let _ = out.write_all(text.as_bytes());
            let _ = out.flush();
            0
        }
        Outcome::Error(text) => {
            let stderr = io::stderr();
            let mut err = stderr.lock();
            let _ = err.write_all(text.as_bytes());
            let _ = err.flush();
            2
        }
    }
}

/// Entry point of the tool, returns the process exit status.
pub fn run() -> i32 {
    let argv: Vec<OsString> = std::env::args_os().collect();
    let m = match cli::parse(argv) {
        Ok(m) => m,
        Err(outcome) => return finish_parse(outcome),
    };
    match execute(&m) {
        Ok(()) => 0,
        Err(()) => 1,
    }
}

/// Run the requested operation with already parsed arguments.
fn execute(m: &Matches) -> Result<(), ()> {
    if let Some(func) = m.get(Id::Func) {
        let places = parse_usize(m, Id::Places, "-p, --places", function_output::DEFAULT_PLACES)?;
        let length = func
            .parse::<u64>()
            .map_err(|e| report_int_error("-u, --func", &e))?;
        function_output::output_function(length, places);
        return Ok(());
    }

    let mut input: Box<dyn Read> = match m.get(Id::InputFile) {
        Some(path) => match File::open(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("error: {}", e);
                return Err(());
            }
        },
        None => Box::new(io::stdin()),
    };

    let cols = parse_usize(m, Id::Cols, "-c, --cols", DEFAULT_COLS)?;
    let len = parse_u64(m, Id::Len, "-l, --len", 0)?;

    let data = match read_input(&mut *input, len) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: {}", e);
            return Err(());
        }
    };

    let stdout = io::stdout();
    let mut out = stdout.lock();

    if let Some(flavour) = m.get(Id::Array).and_then(ArrayFormat::from_arg) {
        print_array(&mut out, &data, cols, flavour);
        let _ = out.flush();
        return Ok(());
    }

    let opts = DumpOptions {
        cols,
        format: Format::from_arg(m.get(Id::Format)),
        prefix: m.get(Id::Prefix) != Some("0"),
        color: use_color(m),
    };
    print_dump(&mut out, &data, &opts);
    let _ = out.flush();
    Ok(())
}

/// Write `width` spaces.
fn write_padding<W: Write>(out: &mut W, width: usize) {
    if width > 0 {
        {
            let _ = write!(out, "{:width$}", "", width = width);
        }
    }
}
